namespace App\Http\Requests;use Illuminate\Foundation\Http\FormRequest;use Illuminate\Validation\Rule;class StoreCommitteeScheduleItemRequest extends FormRequest{public function authorize():bool{return$this->user()?->can('comites.cronograma.gestionar')??false;}public function rules():array{return['activity_type'=>['required',Rule::in(['ordinary_meeting','extraordinary_meeting','inspection','training','campaign','follow_up','report','other'])],'title'=>'required|string|max:255','description'=>'nullable|string|max:3000','scheduled_date'=>'required|date','start_time'=>'nullable|date_format:H:i','end_time'=>'nullable|date_format:H:i|after:start_time','location'=>'nullable|string|max:255','modality'=>['required',Rule::in(['presencial','virtual','mixta'])],'responsible_member_id'=>'nullable|exists:committee_members,id','phva_stage'=>['required',Rule::in(['P','H','V','A'])],'notes'=>'nullable|string|max:2000'];}}
